// Get all tokens currently targeted
const targets = game.user.targets;

// Check if any tokens are targeted
if (targets.size === 0) {
  ui.notifications.warn("Please target at least one token!");
} else {
  // Loop through targeted tokens
  for (let token of targets) {
    const actor = token.actor;
    const currentRisk = actor.system.risk.value ?? 0;

    // Decrease risk but don't let it go below 0
    const newRisk = Math.max(0, currentRisk - 1);

    // Update the value
    await actor.update({ "system.risk.value": newRisk });

    // Notification
    ui.notifications.info(`${token.name} loses 1 Risk. (Now: ${newRisk})`);
  }
}
